DROP TABLE IF EXISTS `spj`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `spj` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `sp2d_id` bigint unsigned NOT NULL,
  `opd_id` bigint unsigned NOT NULL,
  `sp2d_budget_code_id` bigint unsigned DEFAULT NULL,
  `nomor_spj` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tanggal` date NOT NULL,
  `jumlah` decimal(15,2) NOT NULL,
  `status` enum('draft','submitted','in_review','reviewed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `reviewed_by` bigint unsigned DEFAULT NULL,
  `reviewed_at` datetime DEFAULT NULL,
  `review_notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `spj_sp2d_id_foreign` (`sp2d_id`),
  KEY `spj_opd_id_foreign` (`opd_id`),
  KEY `spj_sp2d_budget_code_id_foreign` (`sp2d_budget_code_id`),
  KEY `spj_reviewed_by_foreign` (`reviewed_by`),
  CONSTRAINT `spj_opd_id_foreign` FOREIGN KEY (`opd_id`) REFERENCES `opds` (`id`) ON DELETE CASCADE,
  CONSTRAINT `spj_reviewed_by_foreign` FOREIGN KEY (`reviewed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `spj_sp2d_budget_code_id_foreign` FOREIGN KEY (`sp2d_budget_code_id`) REFERENCES `sp2d_budget_codes` (`id`) ON DELETE CASCADE,
  CONSTRAINT `spj_sp2d_id_foreign` FOREIGN KEY (`sp2d_id`) REFERENCES `sp2d` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
